import {parseSave,editSave,checksum,PROFILE,decodeName} from './core.mjs';
import {ITEMS,SPECIES} from './catalog.mjs';
export const POCKETS=[{id:1,name:'ไอเทมทั่วไป',offset:0x4d0,count:80},{id:2,name:'ยา',offset:0x888,count:40},{id:3,name:'Poké Balls',offset:0x6d8,count:31},{id:4,name:'ไอเทมต่อสู้',offset:0x928,count:100},{id:5,name:'ไอเทมเพิ่มพลัง',offset:0xbd0,count:80},{id:6,name:'ไอเทมประเภท',offset:0xd10,count:47},{id:7,name:'เบอร์รี',offset:0x770,count:70},{id:8,name:'Mega Stones',offset:0xab8,count:70}];
const view=b=>new DataView(b.buffer,b.byteOffset,b.byteLength);
export function nicknameBytes(name){if(!/^[A-Za-z0-9 .-]{1,10}$/.test(name)||!name.trim())throw Error('ชื่อเล่นโปเกมอนใช้ภาษาอังกฤษ ตัวเลข ช่องว่าง จุด หรือขีด 1–10 ตัวอักษร');const b=new Uint8Array(12).fill(255);[...name].forEach((c,i)=>b[i]=c===' '?0:c==='.'?0xad:c==='-'?0xae:/[A-Z]/.test(c)?c.charCodeAt(0)+122:/[a-z]/.test(c)?c.charCodeAt(0)+116:c.charCodeAt(0)+113);return b;}
export function inspectExtras(input){const s=parseSave(input),b=s.bytes,v=view(b),base=s.world,party=[],items=[];const count=b[base+0x234];if(count>6)throw Error('จำนวนโปเกมอนไม่ตรงกับโครงสร้างที่รองรับ');for(let i=0;i<count;i++){const p=base+0x238+i*76,id=v.getUint16(p+0x1c,true)&0xfff,level=b[p+0x3c],hp=v.getUint16(p+0x3e,true),maxHP=v.getUint16(p+0x40,true);if(!SPECIES[id]||level<1||level>100||maxHP<1||hp>maxHP)throw Error('ข้อมูลโปเกมอนมีรูปแบบที่ยังไม่รองรับ');party.push({index:i,offset:p,species:id,speciesName:SPECIES[id],nickname:decodeName(b.slice(p+8,p+20)),level,hp,maxHP,status:v.getUint32(p+0x38,true),egg:!!(b[p+0x27]&128)});}
for(const pocket of POCKETS)for(let slot=0;slot<pocket.count;slot++){const offset=pocket.offset+slot*4,id=v.getUint16(base+offset,true),quantity=v.getUint16(base+offset+2,true)^(s.key&65535);if(id===0){if(quantity!==0)throw Error('ช่องไอเทมว่างมีข้อมูลไม่ตรงรูปแบบ');continue;}const meta=ITEMS[id];if(!meta||meta.pocket!==pocket.id||quantity<1||quantity>9999)throw Error('ข้อมูลกระเป๋ามีรูปแบบที่ยังไม่รองรับ');items.push({offset,id,name:meta.name,pocket:pocket.name,quantity,max:Math.max(99,quantity)});}
return {party,items};}
export function editExtended(input,changes){const s=parseSave(input);let out=editSave(input,changes),v=view(out);if(!(changes.party?.length||changes.items?.length))return out;const actual=inspectExtras(input);for(const change of changes.party||[]){const mon=actual.party.find(m=>m.index===change.index);if(!mon||mon.egg)throw Error('ไม่รองรับการแก้ไขโปเกมอนช่องนี้');if(change.nickname!==undefined&&change.nickname!==mon.nickname)out.set(nicknameBytes(change.nickname),mon.offset+8);if(change.hp!==undefined){if(!Number.isInteger(change.hp)||change.hp<0||change.hp>mon.maxHP)throw Error('HP ต้องอยู่ระหว่าง 0 ถึง HP สูงสุด');v.setUint16(mon.offset+0x3e,change.hp,true);}}
for(const change of changes.items||[]){const item=actual.items.find(i=>i.offset===change.offset);if(!item||item.id!==change.id)throw Error('ช่องไอเทมไม่ตรงกับเซฟต้นฉบับ');if(!Number.isInteger(change.quantity)||change.quantity<1||change.quantity>item.max)throw Error('จำนวนไอเทมต้องอยู่ในช่วงที่แสดง');v.setUint16(s.world+item.offset+2,change.quantity^(s.key&65535),true);}
v.setUint16(s.world+0xff6,checksum(out,s.world,PROFILE.sizes[1]),true);parseSave(out);inspectExtras(out);return out;}
